#include "physics.hpp"
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
using namespace web;using namespace web::physics;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Lab flatLab(){Lab l;l.recipe.broken=0;Patch p;p.corners={V3{0,0,1},V3{.2,0,1},V3{.2,.2,1},V3{0,.2,1}};l.patches={p};return l;}
void add(Lab&l,V2 a,V2 b,int patch=0){int n=int(l.nodes.size()),f=int(l.fibers.size());l.nodes.push_back({n,patch,a});l.nodes.push_back({n+1,patch,b});Fiber edge;edge.id=f;edge.patch=patch;edge.nodeA=n;edge.nodeB=n+1;edge.strand=f;edge.structural=true;edge.uv={a,b};l.fibers.push_back(edge);}
Lab crossingLab(){auto l=flatLab();add(l,{.1,.1},{.9,.9});add(l,{.1,.9},{.9,.1});return l;}
BuildOptions options(){BuildOptions o;o.cohesive=true;o.sampleLength=.5;return o;}
double cross2(V2 a,V2 b){return a.x*b.y-a.y*b.x;}
int unjoined(const Graph&g,bool material){int n=0;size_t count=material?g.cohesive.segments.size():g.edges.size();for(size_t i=0;i<count;++i)for(size_t j=i+1;j<count;++j){V2 a,b,c,d;int ai,bi,ci,di;if(material){auto x=g.cohesive.segments[i],y=g.cohesive.segments[j];a=g.cohesive.vertices[x.a].uv;b=g.cohesive.vertices[x.b].uv;c=g.cohesive.vertices[y.a].uv;d=g.cohesive.vertices[y.b].uv;ai=x.a;bi=x.b;ci=y.a;di=y.b;}else{auto x=g.edges[i],y=g.edges[j];a=g.particles[x.a].uv;b=g.particles[x.b].uv;c=g.particles[y.a].uv;d=g.particles[y.b].uv;ai=x.a;bi=x.b;ci=y.a;di=y.b;}if(ai==ci||ai==di||bi==ci||bi==di)continue;V2 u=b-a,v=d-c;double den=cross2(u,v);if(std::abs(den)<1e-12*length(u)*length(v))continue;double t=cross2(c-a,v)/den,s=cross2(c-a,u)/den;if(t>1e-9&&t<1-1e-9&&s>1e-9&&s<1-1e-9)++n;}return n;}
std::string metadata(const Graph&g){std::ostringstream s;s<<std::setprecision(17)<<g.cohesive.junctions<<' '<<g.cohesive.depthRejected<<' '<<g.cohesive.maxRestShapeError;for(const auto&v:g.cohesive.vertices)s<<' '<<v.uv.x<<' '<<v.uv.y<<' '<<v.rest.x<<' '<<v.rest.y<<' '<<v.rest.z<<' '<<v.particle;for(const auto&e:g.cohesive.segments)s<<' '<<e.a<<' '<<e.b<<' '<<e.edge<<' '<<e.parentEdge;return s.str();}
void flatCrossing(){auto l=crossingLab();auto o=options();o.cohesive=false;auto baseline=buildGraph(l,o);check(baseline.particles.size()==4&&baseline.edges.size()==2,"fixture has two independent crossing segments");o.cohesive=true;auto g=buildGraph(l,o);check(g.particles.size()==5&&g.edges.size()==4,"cohesive graph must split both UV segments at one shared crossing particle");int middle=-1;for(const auto&p:g.particles)if(length(p.uv-V2{.5,.5})<1e-10)middle=p.id;check(middle>=0,"crossing UV junction exists");int degree=0;for(const auto&e:g.edges)degree+=(e.a==middle||e.b==middle);check(degree==4,"crossing children share exactly one particle");check(length(g.particles[middle].rest-l.patches[0].sample({.5,.5}))<1e-14,"crossing rest uses carrier sample");for(const auto&s:g.cohesive.segments)check(s.parentEdge>=0&&s.parentEdge<2,"child retains original sampled-edge identity");check(unjoined(g,false)==0&&unjoined(g,true)==0,"flat crossing planar before and after cluster");}
void aliasesAndOverlap(){auto l=flatLab();add(l,{.1,.5},{.9,.5});add(l,{.3,.5},{.7,.5});add(l,{.3,.5},{.3,.9});auto g=buildGraph(l,options());check(g.particles.size()==5&&g.edges.size()==5,"collinear overlap endpoints split long segment and share T junction");std::set<int> ids;bool aliased=false;for(const auto&p:g.particles){for(int id:p.sourceNodes)ids.insert(id);aliased|=p.sourceNodes==std::vector<int>({2,4});}check(ids==std::set<int>({0,1,2,3,4,5})&&aliased,"coincident source-node aliases retained");int duplicateSpan=0;for(const auto&e:g.edges)if(std::abs(e.rest-.08)<1e-12&&std::abs(g.particles[e.a].uv.y-.5)<1e-12&&std::abs(g.particles[e.b].uv.y-.5)<1e-12)++duplicateSpan;check(duplicateSpan==2,"coincident original fibers retain separate material strength");}
void depthAndPatchIsolation(){auto l=crossingLab();l.patches[0].bulge={0,0,.3};auto o=options();auto g=buildGraph(l,o);check(g.cohesive.depthRejected>0&&g.cohesive.junctions==0,"curved chord crossing outside declared rest-depth tolerance is not joined");l=crossingLab();auto second=l.patches[0];second.id=1;second.layer=1;for(auto&c:second.corners)c.z+=.02;l.patches.push_back(second);add(l,{.1,.5},{.9,.5},1);auto first=buildGraph(l,o);o.patch=1;auto layer=buildGraph(l,o);check(first.particles.size()==5&&layer.particles.size()==2,"no connections across distinct patches or layers");for(const auto&p:first.particles)for(int id:p.sourceNodes)check(l.nodes[id].patch==0,"source provenance stays in selected patch");}
void anchorsStayDistinct(){auto l=flatLab();add(l,{.3,.5},{.31,.5});l.anchors={{42,l.patches[0].sample({.3,.5})},{99,l.patches[0].sample({.31,.5})}};auto g=buildGraph(l,options());check(g.particles.size()==2&&g.edges.size()==1,"different anchors cannot contract even below 5 mm");for(const auto&p:g.particles){auto a=std::find_if(l.anchors.begin(),l.anchors.end(),[&](const Anchor&x){return x.id==p.anchor;});check(a!=l.anchors.end()&&length(p.rest-a->position)==0&&p.invMass==0,"world anchor ID and coordinates stay exact");}}
void corridor(){for(unsigned seed:{42,99}){Recipe r;r.preset="corridor";r.seed=seed;r.density=.9;r.width=.0045;r.broken=0;r.quality=20;auto l=generate(r);BuildOptions o;auto baseline=buildGraph(l,o);o.cohesive=true;auto g=buildGraph(l,o),same=buildGraph(l,o);check(saveState(g)==saveState(same)&&metadata(g)==metadata(same),"same-seed cohesive graph and immutable metadata deterministic");check(g.particles.size()+128<=2048&&g.edges.size()+512<=4096,"hard budgets include contact and particle reserves");check(g.cohesive.depthRejected==0&&g.cohesive.maxRestShapeError<=.005,"all corridor crossing rest shapes meet explicit 5 mm tolerance");check(unjoined(g,false)==0&&unjoined(g,true)==0,"no remaining proper crossings in physical or exact material UV");std::set<int> aliases;for(const auto&p:g.particles)for(int id:p.sourceNodes)aliases.insert(id);for(const auto&p:baseline.particles)for(int id:p.sourceNodes)check(aliases.count(id),"all baseline source aliases preserved");for(const auto&v:g.cohesive.vertices)check(v.particle>=0&&v.particle<int(g.particles.size())&&length(v.rest-l.patches[0].sample(v.uv))<1e-10&&length(v.rest-g.particles[v.particle].rest)<=.00500000001,"immutable UV vertex maps to physical particle within cluster tolerance");for(const auto&s:g.cohesive.segments){check(s.parentEdge>=0&&s.edge<int(g.edges.size()),"valid material parent and child edge mapping");if(s.edge>=0){const auto&e=g.edges[s.edge];check(g.cohesive.vertices[s.a].particle==e.a&&g.cohesive.vertices[s.b].particle==e.b,"material edges map to physical edge endpoints");}else check(g.cohesive.vertices[s.a].particle==g.cohesive.vertices[s.b].particle,"contracted material edge remains visible in embedding");}
auto profile=profiles();std::vector<double> mass(g.particles.size(),0);for(const auto&e:g.edges){check(std::abs(e.compliance-profile[e.kind].compliance*e.rest)<1e-15,"child compliance proportional to final rest length");mass[e.a]+=.5*e.rest*profile[e.kind].massPerLength;mass[e.b]+=.5*e.rest*profile[e.kind].massPerLength;}for(size_t i=0;i<mass.size();++i)if(g.particles[i].anchor<0)check(std::abs(g.particles[i].invMass*std::max(.001,mass[i])*o.massScale-1)<1e-12,"cohesive mass recomputed from final length with original mass floor");o.width=2;auto wide=buildGraph(l,o);o.width=1;o.strength=2;auto strong=buildGraph(l,o);for(size_t i=0;i<g.edges.size();++i){check(wide.edges[i].compliance==g.edges[i].compliance&&wide.edges[i].strength==g.edges[i].strength&&wide.edges[i].width==2*g.edges[i].width,"width independent from stiffness and strength");check(strong.edges[i].compliance==g.edges[i].compliance&&strong.edges[i].strength==2*g.edges[i].strength,"strength independent from stiffness and width");}std::cout<<"PASS corridor seed="<<seed<<" particles="<<g.particles.size()<<" edges="<<g.edges.size()<<" junctions="<<g.cohesive.junctions<<" max_rest_error="<<g.cohesive.maxRestShapeError<<" physical_crossings=0 material_crossings=0\n";}}
void budget(){auto l=flatLab();for(int i=0;i<45;++i){double t=(i+1)/46.;add(l,{.01,t},{.99,t});add(l,{t,.01},{t,.99});}bool rejected=false;try{buildGraph(l,options());}catch(const std::runtime_error&e){rejected=std::string(e.what()).find("budget exceeded")!=std::string::npos;}check(rejected,"overbudget crossing expansion rejects without truncation");}
int main(){try{flatCrossing();aliasesAndOverlap();depthAndPatchIsolation();anchorsStayDistinct();corridor();budget();std::cout<<"PASS cohesive graph contracts\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
